                            const curAngle = ray.angle + Math.sin(frame * ray.speed + idx) * 0.06;
                            const pulse = 0.86 + 0.14 * Math.sin(frame * ray.pulseSpeed + ray.pulseOffset);
                            const rayLen = ray.length * (0.9 + 0.22 * crystalPulse) * pulse;
                            const rayW = ray.width * pulse;
                            const rayAlpha = ray.baseAlpha * godRayIntensity * (0.8 + 0.2 * pulse);

