                    const dy = targetY - crystalHeadY;
                    const totalDist = Math.hypot(dx, dy) || 1;
                    const nx = -dy / totalDist;
                    const ny = dx / totalDist;
                    const ux = dx / totalDist;
                    const uy = dy / totalDist;

