        const setActionBar = window.setActionBar || (window.LotrEngine && window.LotrEngine.setActionBar);
        const setActionInfo = window.setActionInfo || (window.LotrEngine && window.LotrEngine.setActionInfo);
        const resolveEnemyAttacks = window.resolveEnemyAttacks || (window.LotrEngine && window.LotrEngine.resolveEnemyAttacks);
        const playerAttacks = window.playerAttacks || (window.LotrEngine && window.LotrEngine.playerAttacks);
