    window.executeLightInTheDarkEvent = function(card, finishEvent, refundEvent) {
        const game = window.game || (window.LotrEngine && window.LotrEngine.game);
        if (!game) { if (refundEvent) refundEvent(); return; }

        const validTargets = game.engagedEnemies.filter(e => !e._notActuallyEngaged && !e._isWolfRiderAttacking);
        if (validTargets.length === 0) {
            const toast = window.toast || (window.LotrEngine && window.LotrEngine.toast);
            if (typeof toast === 'function') {
                toast('A Light in the Dark', 'No valid engaged enemies (Wolf Rider acting as shadow card is not engaged).', 'info');
            }
            if (refundEvent) refundEvent();
            return;
        }

        const showEnemyPicker = window.showEnemyPicker || (window.LotrEngine && window.LotrEngine.showEnemyPicker);
        if (typeof showEnemyPicker !== 'function') {
            if (refundEvent) refundEvent();
            return;
        }

        showEnemyPicker('A Light in the Dark', '<span style="font-size:1.6rem; font-weight:600; color:var(--gold-bright); display:block; margin-bottom:12px; line-height:1.35;">Choose an enemy to return to the Staging Area:</span>', validTargets, (enemy) => {
            if (enemy) {
                if (window.SoundFX && typeof window.SoundFX.playALightInTheDark === 'function') {
                    window.SoundFX.playALightInTheDark();
                }

                // Capture current active buttons and action info before clearing bar
                const preEventButtons = window._lastGoodActionBarButtons;
                const preEventInfo = window._lastGoodActionInfoText;

                let applied = false;
                const applyReturn = () => {
                    if (applied) return;
                    applied = true;
                    window.applyLightInTheDarkReturn(enemy, preEventButtons, preEventInfo);
                };

                let startEl = document.querySelector(`.zone-content [data-uid="${card._uid}"]`);
                if (!startEl) startEl = document.querySelector(`[data-uid="${card._uid}"]`);
                
                let sRect = startEl ? startEl.getBoundingClientRect() : null;
                if (!sRect || sRect.width === 0) {
                    const handZone = document.getElementById('hand-content');
                    if (handZone) sRect = handZone.getBoundingClientRect();
                    if (!sRect || sRect.width === 0) {
                        const discardEl = document.getElementById('player-discard-pile');
                        if (discardEl) sRect = discardEl.getBoundingClientRect();
                    }
                }

                if (typeof window.setActionBar === 'function') {
                    window.setActionBar([]);
                }
                if (typeof finishEvent === 'function') {
                    finishEvent();
                }

                // Safety fallback timeout in case animations are interrupted or cancelled
                setTimeout(() => {
                    if (!applied) applyReturn();
                }, 2200);

                if (typeof window.triggerLightInTheDarkEffect === 'function') {
                    window.triggerLightInTheDarkEffect(enemy._uid, sRect, () => {
                        if (typeof window.animateReturnToStaging === 'function') {
                            window.animateReturnToStaging(enemy, applyReturn);
                        } else {
                            applyReturn();
                        }
                    });
                } else if (typeof window.animateReturnToStaging === 'function') {
                    window.animateReturnToStaging(enemy, applyReturn);
                } else {
                    applyReturn();
                }
            } else {
                if (typeof refundEvent === 'function') refundEvent();
            }
        }, 'Cancel');
    };

    // --- BLADE OF GONDOLIN: PROGRESS RESPONSE EFFECT ---
    // When the hero with Blade of Gondolin attached destroys an enemy, a brilliant Elven starlight
    // projectile shoots out from the Blade of Gondolin and arcs across to the top-left quest card,
    // landing with a radiant impact, progress token emblem, and +1 Progress!
    window.triggerBladeOfGondolinProgressEffect = function(bladeUid, heroUid, onComplete) {
        const bladeEl = document.querySelector(`[data-uid="${bladeUid}"]`);
        const heroEl = document.querySelector(`[data-uid="${heroUid}"]`);
        const originEl = bladeEl || heroEl;
        if (!originEl) {
            if (onComplete) onComplete();
            return;
        }

        const questEl = document.querySelector('#quest-content .card') || document.querySelector('#quest-zone') || document.querySelector('.zone-quest');
        const bRect = originEl.getBoundingClientRect();
        const qRect = questEl ? questEl.getBoundingClientRect() : { left: 80, top: 120, width: 150, height: 210 };

        const sx = bRect.left + bRect.width / 2;
        const sy = bRect.top + bRect.height / 2;
        const tx = qRect.left + qRect.width / 2;
        const ty = qRect.top + qRect.height / 2;

        // Synthesized shimmering Elven resonance chime (no mp3 on defeat trigger)
        try {
            const AudioCtx = window.AudioContext || window.webkitAudioContext;
            if (AudioCtx) {
                const actx = new AudioCtx();
                const now = actx.currentTime;
                // E-minor / A-major shimmering chord tones: First Age Elven steel singing
                [587.33, 880, 1174.66, 1760].forEach((freq, i) => {
                    const osc = actx.createOscillator();
                    const gain = actx.createGain();
                    osc.type = 'triangle';
                    osc.frequency.setValueAtTime(freq, now + i * 0.04);
                    gain.gain.setValueAtTime(0.09, now + i * 0.04);
                    gain.gain.exponentialRampToValueAtTime(0.0001, now + i * 0.04 + 0.65);
                    osc.connect(gain);
                    gain.connect(actx.destination);
                    osc.start(now + i * 0.04);
                    osc.stop(now + i * 0.04 + 0.7);
                });
            }
        } catch (e) {}

        // Glow and flash on card face, scaling smoothly up and back down at origin (preserving orientation if exhausted)
        const isBladeExhausted = bladeEl && bladeEl.classList.contains('exhausted');
        const bladeBaseRotate = isBladeExhausted ? 'rotate(90deg) ' : '';

        if (bladeEl) {
            bladeEl.style.zIndex = '60';
            bladeEl.style.transition = 'transform 0.24s cubic-bezier(0.2, 0.9, 0.3, 1.2), box-shadow 0.24s ease, filter 0.24s ease';
            bladeEl.style.filter = 'brightness(1.75) contrast(1.18)';
            bladeEl.style.boxShadow = '0 0 35px rgba(56, 189, 248, 0.85), 0 0 60px rgba(0, 229, 255, 0.5), inset 0 0 25px rgba(220, 245, 255, 0.65)';
            bladeEl.style.transform = `${bladeBaseRotate}scale(1.18)`;
            setTimeout(() => {
                bladeEl.style.transition = 'transform 0.7s cubic-bezier(0.25, 1, 0.5, 1), box-shadow 0.7s ease, filter 0.7s ease';
                bladeEl.style.filter = '';
                bladeEl.style.boxShadow = '';
                bladeEl.style.transform = `${bladeBaseRotate}scale(1)`;
                setTimeout(() => {
                    bladeEl.style.transition = '';
                    bladeEl.style.transform = '';
                    bladeEl.style.zIndex = '';
                }, 750);
            }, 260);
        } else if (heroEl) {
            const isHeroExhausted = heroEl.classList.contains('exhausted');
            const heroBaseRotate = isHeroExhausted ? 'rotate(90deg) ' : '';
            heroEl.style.zIndex = '60';
            heroEl.style.transition = 'transform 0.24s cubic-bezier(0.2, 0.9, 0.3, 1.2), box-shadow 0.24s ease, filter 0.24s ease';
            heroEl.style.filter = 'brightness(1.65) contrast(1.15)';
            heroEl.style.boxShadow = '0 0 30px rgba(56, 189, 248, 0.8), 0 0 55px rgba(0, 229, 255, 0.45), inset 0 0 25px rgba(220, 245, 255, 0.6)';
            heroEl.style.transform = `${heroBaseRotate}scale(1.12)`;
            setTimeout(() => {
                heroEl.style.transition = 'transform 0.7s cubic-bezier(0.25, 1, 0.5, 1), box-shadow 0.7s ease, filter 0.7s ease';
                heroEl.style.filter = '';
                heroEl.style.boxShadow = '';
                heroEl.style.transform = `${heroBaseRotate}scale(1)`;
                setTimeout(() => {
                    heroEl.style.transition = '';
                    heroEl.style.transform = '';
                    heroEl.style.zIndex = '';
                }, 750);
            }, 260);
        }

        // Create full-screen overlay canvas
        const canvas = document.createElement('canvas');
        const dpr = window.devicePixelRatio || 1;
        const w = window.innerWidth;
        const h = window.innerHeight;
        canvas.width = w * dpr;
        canvas.height = h * dpr;
        canvas.style.cssText = `
            position: fixed; inset: 0; width: 100vw; height: 100vh;
            pointer-events: none; z-index: 999999;
        `;
        document.body.appendChild(canvas);

        const ctx = canvas.getContext('2d');
        ctx.scale(dpr, dpr);

        // Calculate arched trajectory
        const midX = (sx + tx) / 2;
        const midY = (sy + ty) / 2;
        const dist = Math.hypot(tx - sx, ty - sy);
        const arcHeight = Math.min(230, Math.max(120, dist * 0.28));
        const ctrlX = midX - 45;
        const ctrlY = Math.min(sy, ty) - arcHeight;

        function getBezier(t) {
            const inv = 1 - t;
            const x = inv * inv * sx + 2 * inv * t * ctrlX + t * t * tx;
            const y = inv * inv * sy + 2 * inv * t * ctrlY + t * t * ty;
            const dx = 2 * inv * (ctrlX - sx) + 2 * t * (tx - ctrlX);
            const dy = 2 * inv * (ctrlY - sy) + 2 * t * (ty - ctrlY);
            const angle = Math.atan2(dy, dx);
            return { x, y, angle };
        }

        const flightDuration = 52;
        let frame = 0;
        const trail = [];
        const particles = [];
        const shockwaves = [];
        let impactTriggered = false;

        function spawnImpactParticles(ix, iy) {
            for (let i = 0; i < 48; i++) {
                const angle = Math.random() * Math.PI * 2;
                const spd = 1.6 + Math.random() * 6.5;
                const colors = ['#ffffff', '#e0f2fe', '#38bdf8', '#00e5ff', '#f5d76e', '#ffd700'];
                particles.push({
                    x: ix, y: iy,
                    vx: Math.cos(angle) * spd,
                    vy: Math.sin(angle) * spd - 0.4,
                    size: 1.6 + Math.random() * 3.4,
                    color: colors[Math.floor(Math.random() * colors.length)],
                    alpha: 1.0,
                    decay: 0.016 + Math.random() * 0.02,
                    isImpact: true,
                    rot: Math.random() * Math.PI * 2,
                    vRot: (Math.random() - 0.5) * 0.12
                });
            }
        }

        // Draw glowing First Age Elven Dagger silhouette at projectile head
        function drawElvenBladeHead(cx, cy, angle, scale, glowAlpha) {
            ctx.save();
            ctx.translate(cx, cy);
            ctx.rotate(angle);
            ctx.scale(scale, scale);

            // Outer radiant starlight aura
            ctx.shadowColor = '#00e5ff';
            ctx.shadowBlur = 18;

            // Blade gradient
            const bGrad = ctx.createLinearGradient(0, 0, 32, 0);
            bGrad.addColorStop(0, '#bae6fd');
            bGrad.addColorStop(0.3, '#38bdf8');
            bGrad.addColorStop(0.7, '#e0f2fe');
            bGrad.addColorStop(1, '#ffffff');

            // Tapered double-edged elven blade pointing forward (+X)
            ctx.fillStyle = bGrad;
            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 1.0;
            ctx.beginPath();
            ctx.moveTo(34, 0); // Blade tip
            ctx.quadraticCurveTo(18, -5.5, -4, -4.5); // Top edge
            ctx.lineTo(-7, 0); // Tang / base
            ctx.lineTo(-4, 4.5); // Bottom edge
            ctx.quadraticCurveTo(18, 5.5, 34, 0);
            ctx.closePath();
            ctx.fill();
            ctx.stroke();

            // Central faceted fuller / spine with bright glint
            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 0.9;
            ctx.beginPath();
            ctx.moveTo(-5, 0);
            ctx.lineTo(31, 0);
            ctx.stroke();

            // Golden filigree collar & pommel
            ctx.fillStyle = '#f5d76e';
            ctx.strokeStyle = '#d4af37';
            ctx.lineWidth = 0.8;
            ctx.beginPath();
            ctx.arc(-7, 0, 3.2, 0, Math.PI * 2);
            ctx.fill();
            ctx.stroke();

            // Cross-star lens flare at the tip
            const flareLen = 14 + Math.sin(frame * 0.3) * 4;
            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 1.4;
            ctx.beginPath();
            ctx.moveTo(34 - flareLen, 0); ctx.lineTo(34 + flareLen, 0);
            ctx.moveTo(34, -flareLen * 0.65); ctx.lineTo(34, flareLen * 0.65);
            ctx.stroke();

            ctx.restore();
        }

        function loop() {
            ctx.clearRect(0, 0, w, h);
            frame++;

            if (frame <= flightDuration) {
                const t = frame / flightDuration;
                const pos = getBezier(t);

                // Add to ribbon trail
                trail.push({ x: pos.x, y: pos.y, angle: pos.angle, time: frame });
                if (trail.length > 22) trail.shift();

                // Draw starlight comet tail ribbon
                for (let i = 1; i < trail.length; i++) {
                    const tr = trail[i];
                    const prev = trail[i - 1];
                    const trAlpha = (i / trail.length) * 0.85;
                    const trWidth = (i / trail.length) * 9.0;

                    ctx.save();
                    ctx.globalAlpha = trAlpha;
                    ctx.strokeStyle = '#38bdf8';
                    ctx.shadowColor = '#00e5ff';
                    ctx.shadowBlur = 14;
                    ctx.lineWidth = trWidth;
                    ctx.lineCap = 'round';
                    ctx.beginPath();
                    ctx.moveTo(prev.x, prev.y);
                    ctx.lineTo(tr.x, tr.y);
                    ctx.stroke();

                    // Bright inner core
                    ctx.strokeStyle = '#ffffff';
                    ctx.lineWidth = Math.max(1, trWidth * 0.35);
                    ctx.stroke();
                    ctx.restore();
                }

                // Spawn trailing stardust sparks
                for (let k = 0; k < 3; k++) {
                    const sparkAngle = pos.angle + Math.PI + (Math.random() - 0.5) * 1.2;
                    const spd = 0.5 + Math.random() * 2.5;
                    particles.push({
                        x: pos.x + (Math.random() - 0.5) * 8,
                        y: pos.y + (Math.random() - 0.5) * 8,
                        vx: Math.cos(sparkAngle) * spd,
                        vy: Math.sin(sparkAngle) * spd,
                        size: 1.4 + Math.random() * 2.4,
                        color: Math.random() > 0.4 ? '#38bdf8' : (Math.random() > 0.4 ? '#ffffff' : '#f5d76e'),
                        alpha: 1.0,
                        decay: 0.025 + Math.random() * 0.025,
                        isImpact: false,
                        rot: Math.random() * Math.PI * 2,
                        vRot: (Math.random() - 0.5) * 0.1
                    });
                }

                // Draw the glowing Elven blade head
                const headScale = 0.95 + Math.sin(frame * 0.25) * 0.08;
                drawElvenBladeHead(pos.x, pos.y, pos.angle, headScale, 1.0);
            }

            // Impact at the top-left quest card
            if (frame === flightDuration && !impactTriggered) {
                impactTriggered = true;
                spawnImpactParticles(tx, ty);

                // Expanding shockwaves
                shockwaves.push({ r: 4, maxR: 95, color: '#38bdf8', width: 3.5, alpha: 1.0 });
                shockwaves.push({ r: 2, maxR: 75, color: '#f5d76e', width: 2.5, alpha: 1.0 });

                if (window.LotrEngine && window.LotrEngine.screenShake) {
                    window.LotrEngine.screenShake(6, 220);
                }

                // Illuminate the top-left quest card with gentle glow
                const freshQuestEl = document.querySelector('#quest-content .card') || document.querySelector('#quest-zone') || document.querySelector('.zone-quest');
                if (freshQuestEl) {
                    freshQuestEl.style.transition = 'transform 0.2s ease-out, box-shadow 0.2s ease, filter 0.2s ease';
                    freshQuestEl.style.filter = 'brightness(1.3) contrast(1.08)';
                    freshQuestEl.style.boxShadow = '0 0 25px rgba(56, 189, 248, 0.7), 0 0 45px rgba(245, 215, 110, 0.4)';
                    freshQuestEl.style.transform = 'scale(1.05)';
                    setTimeout(() => {
                        freshQuestEl.style.transition = 'all 0.6s cubic-bezier(0.25, 0.8, 0.25, 1)';
                        freshQuestEl.style.filter = '';
                        freshQuestEl.style.boxShadow = '';
                        freshQuestEl.style.transform = '';
                    }, 220);
                }

                // Floating text directly over the top-left quest card with 3.0s duration and non-overlapping stack offset
                const qCenter = freshQuestEl ? freshQuestEl.getBoundingClientRect() : qRect;
                const qCenterX = qCenter.left + qCenter.width / 2;
                const qCenterY = qCenter.top + qCenter.height / 2;

                window._questProgressStackCount = window._questProgressStackCount || 0;
                const stackIdx = window._questProgressStackCount;
                window._questProgressStackCount++;
                setTimeout(() => {
                    window._questProgressStackCount = Math.max(0, (window._questProgressStackCount || 1) - 1);
                }, 3000);
                const stackYOffset = stackIdx * 38;

                let style = document.getElementById('blade-progress-text-style');
                if (!style) {
                    style = document.createElement('style');
                    style.id = 'blade-progress-text-style';
                    document.head.appendChild(style);
                }
                style.textContent = `
                    @keyframes bladeProgressFloat {
                        0% { opacity: 0; transform: translate(-50%, -50%) scale(0.8); }
                        15% { opacity: 1; transform: translate(-50%, calc(-50% - 18px)) scale(1.15); }
                        75% { opacity: 1; transform: translate(-50%, calc(-50% - 35px)) scale(1); }
                        100% { opacity: 0; transform: translate(-50%, calc(-50% - 52px)) scale(0.9); }
                    }
                `;
                const floatTxt = document.createElement('div');
                floatTxt.textContent = '+1 Progress!';
                floatTxt.style.cssText = `
                    position: fixed; left: ${qCenterX}px; top: ${qCenterY - stackYOffset}px;
                    color: #f5d76e; font-family: 'Cinzel', serif; font-weight: 900; font-size: 2.2rem;
                    text-shadow: 0 2px 8px #000, 0 0 16px #38bdf8, 0 0 30px rgba(245, 215, 110, 0.8);
                    z-index: 999999; pointer-events: none;
                    white-space: nowrap; text-align: center;
                    animation: bladeProgressFloat 3.0s ease-out forwards;
                `;
                document.body.appendChild(floatTxt);
                setTimeout(() => floatTxt.remove(), 3100);

                // Progress chime on landing
                try {
                    const AudioCtx = window.AudioContext || window.webkitAudioContext;
                    if (AudioCtx) {
                        const actx = new AudioCtx();
                        const now = actx.currentTime;
                        [523.25, 659.25, 1046.5].forEach((freq, i) => {
                            const osc = actx.createOscillator();
                            const gain = actx.createGain();
                            osc.type = 'sine';
                            osc.frequency.setValueAtTime(freq, now + i * 0.06);
                            gain.gain.setValueAtTime(0.1, now + i * 0.06);
                            gain.gain.exponentialRampToValueAtTime(0.0001, now + i * 0.06 + 0.7);
                            osc.connect(gain);
                            gain.connect(actx.destination);
                            osc.start(now + i * 0.06);
                            osc.stop(now + i * 0.06 + 0.75);
                        });
                    }
                } catch (e) {}

                // Execute callback to apply actual progress to the quest in game state
                if (onComplete) onComplete();
            }

            // Draw expanding shockwaves at impact
            for (let i = shockwaves.length - 1; i >= 0; i--) {
                const sw = shockwaves[i];
                sw.r += 3.2;
                sw.alpha = Math.max(0, 1 - sw.r / sw.maxR);
                if (sw.alpha <= 0) {
                    shockwaves.splice(i, 1);
                    continue;
                }
                ctx.save();
                ctx.globalAlpha = sw.alpha;
                ctx.strokeStyle = sw.color;
                ctx.lineWidth = sw.width * sw.alpha;
                ctx.shadowColor = sw.color;
                ctx.shadowBlur = 12;
                ctx.beginPath();
                ctx.arc(tx, ty, sw.r, 0, Math.PI * 2);
                ctx.stroke();
                ctx.restore();
            }

            // Draw and update particles
            for (let i = particles.length - 1; i >= 0; i--) {
                const p = particles[i];
                p.x += p.vx;
                p.y += p.vy;
                p.alpha -= p.decay;
                p.rot += p.vRot;

                if (p.isImpact) {
                    p.vx *= 0.94;
                    p.vy = p.vy * 0.94 + 0.08;
                } else {
                    p.vx *= 0.97;
                    p.vy *= 0.97;
                }

                if (p.alpha <= 0) {
                    particles.splice(i, 1);
                    continue;
                }

                ctx.save();
                ctx.globalAlpha = Math.max(0, p.alpha);
                ctx.translate(p.x, p.y);
                ctx.rotate(p.rot);
                ctx.fillStyle = p.color;
                ctx.shadowColor = p.color;
                ctx.shadowBlur = p.size * 2;

                ctx.beginPath();
                ctx.arc(0, 0, p.size, 0, Math.PI * 2);
                ctx.fill();

                if (p.isImpact && p.size > 2.2) {
                    const ray = p.size * 1.8 * p.alpha;
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = 0.7;
                    ctx.beginPath();
                    ctx.moveTo(-ray, 0); ctx.lineTo(ray, 0);
                    ctx.moveTo(0, -ray); ctx.lineTo(0, ray);
                    ctx.stroke();
                }
                ctx.restore();
            }

            if (frame < flightDuration + 65 || particles.length > 0 || shockwaves.length > 0) {
                requestAnimationFrame(loop);
            } else {
                canvas.remove();
            }
        }
        requestAnimationFrame(loop);
    };

    // --- LEGOLAS: PROGRESS RESPONSE EFFECT ---
    // When Legolas participates in an attack that destroys an enemy, his card immediately
    // flashes bright red, scales up and scales down, and fires an arced starlight projectile
    // across to the top-left quest card, landing with an impact, quest flash, and +2 Progress!
    window.triggerLegolasProgressEffect = function(heroUid, onComplete) {
        let heroEl = document.querySelector(`[data-uid="${heroUid}"]`);
        if (!heroEl) {
            heroEl = document.querySelector('.card.tactics[data-uid]');
        }
        if (!heroEl) {
            if (onComplete) onComplete();
            return;
        }

        const questEl = document.querySelector('#quest-content .card') || document.querySelector('#quest-zone') || document.querySelector('.zone-quest');
        const hRect = heroEl.getBoundingClientRect();
        const qRect = questEl ? questEl.getBoundingClientRect() : { left: 80, top: 120, width: 150, height: 210 };

        const sx = hRect.left + hRect.width / 2;
        const sy = hRect.top + hRect.height / 2;
        const tx = qRect.left + qRect.width / 2;
        const ty = qRect.top + qRect.height / 2;

        // Sound effect (Silvan bow twang + high sparkling starlight chime)
        try {
            const snd = new Audio('./sound_effects/bow_shoot.mp3');
            snd.volume = 0.6;
            snd.play().catch(() => {});
        } catch (e) {}

        try {
            const AudioCtx = window.AudioContext || window.webkitAudioContext;
            if (AudioCtx) {
                const actx = new AudioCtx();
                const now = actx.currentTime;
                // Bowstring release twang
                const bowOsc = actx.createOscillator();
                const bowGain = actx.createGain();
                bowOsc.type = 'sawtooth';
                bowOsc.frequency.setValueAtTime(320, now);
                bowOsc.frequency.exponentialRampToValueAtTime(110, now + 0.12);
                bowGain.gain.setValueAtTime(0.12, now);
                bowGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.14);
                bowOsc.connect(bowGain);
                bowGain.connect(actx.destination);
                bowOsc.start(now);
                bowOsc.stop(now + 0.15);

                // Silvan starlight chime chord: E5, G#5, B5, E6
                [659.25, 830.61, 987.77, 1318.51].forEach((freq, i) => {
                    const osc = actx.createOscillator();
                    const gain = actx.createGain();
                    osc.type = 'triangle';
                    osc.frequency.setValueAtTime(freq, now + 0.05 + i * 0.035);
                    gain.gain.setValueAtTime(0.09, now + 0.05 + i * 0.035);
                    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.05 + i * 0.035 + 0.65);
                    osc.connect(gain);
                    gain.connect(actx.destination);
                    osc.start(now + 0.05 + i * 0.035);
                    osc.stop(now + 0.05 + i * 0.035 + 0.7);
                });
            }
        } catch (e) {}

        // Flash Legolas card with bright Tactics red on the card face, scaling smoothly up and back down (preserving orientation if exhausted)
        const isLegolasExhausted = heroEl.classList.contains('exhausted');
        const legolasBaseRotate = isLegolasExhausted ? 'rotate(90deg) ' : '';

        heroEl.style.zIndex = '60';
        heroEl.style.transition = 'transform 0.24s cubic-bezier(0.2, 0.9, 0.3, 1.2), box-shadow 0.24s ease, filter 0.24s ease';
        heroEl.style.filter = 'brightness(1.75) contrast(1.18) drop-shadow(0 0 20px rgba(239, 68, 68, 0.65))';
        heroEl.style.boxShadow = '0 0 35px rgba(239, 68, 68, 0.8), 0 0 60px rgba(220, 38, 38, 0.5), inset 0 0 30px rgba(255, 180, 180, 0.65)';
        heroEl.style.transform = `${legolasBaseRotate}scale(1.16)`;

        setTimeout(() => {
            heroEl.style.transition = 'transform 0.55s cubic-bezier(0.25, 1, 0.5, 1), box-shadow 0.55s ease, filter 0.55s ease';
            heroEl.style.filter = '';
            heroEl.style.boxShadow = '';
            heroEl.style.transform = `${legolasBaseRotate}scale(1)`;
            setTimeout(() => {
                heroEl.style.transition = '';
                heroEl.style.transform = '';
                heroEl.style.zIndex = '';
            }, 600);
        }, 260);

        // Full-screen overlay canvas for the arced starlight projectile
        const canvas = document.createElement('canvas');
        const dpr = window.devicePixelRatio || 1;
        const w = window.innerWidth;
        const h = window.innerHeight;
        canvas.width = w * dpr;
        canvas.height = h * dpr;
        canvas.style.cssText = `
            position: fixed; inset: 0; width: 100vw; height: 100vh;
            pointer-events: none; z-index: 999999;
        `;
        document.body.appendChild(canvas);

        const ctx = canvas.getContext('2d');
        ctx.scale(dpr, dpr);

        // Calculate arched trajectory
        const midX = (sx + tx) / 2;
        const midY = (sy + ty) / 2;
        const dist = Math.hypot(tx - sx, ty - sy);
        const arcHeight = Math.min(240, Math.max(130, dist * 0.3));
        const ctrlX = midX - 40;
        const ctrlY = Math.min(sy, ty) - arcHeight;

        function getBezier(t) {
            const inv = 1 - t;
            const x = inv * inv * sx + 2 * inv * t * ctrlX + t * t * tx;
            const y = inv * inv * sy + 2 * inv * t * ctrlY + t * t * ty;
            const dx = 2 * inv * (ctrlX - sx) + 2 * t * (tx - ctrlX);
            const dy = 2 * inv * (ctrlY - sy) + 2 * t * (ty - ctrlY);
            const angle = Math.atan2(dy, dx);
            return { x, y, angle };
        }

        const flightDuration = 52;
        let frame = 0;
        const trail = [];
        const particles = [];
        const shockwaves = [];
        let impactTriggered = false;

        function spawnImpactParticles(ix, iy) {
            for (let i = 0; i < 54; i++) {
                const angle = Math.random() * Math.PI * 2;
                const spd = 1.8 + Math.random() * 6.8;
                const colors = ['#ffffff', '#fee2e2', '#f87171', '#ef4444', '#f5d76e', '#ffd700'];
                particles.push({
                    x: ix, y: iy,
                    vx: Math.cos(angle) * spd,
                    vy: Math.sin(angle) * spd - 0.4,
                    size: 1.6 + Math.random() * 3.6,
                    color: colors[Math.floor(Math.random() * colors.length)],
                    alpha: 1.0,
                    decay: 0.016 + Math.random() * 0.02,
                    isImpact: true,
                    rot: Math.random() * Math.PI * 2,
                    vRot: (Math.random() - 0.5) * 0.12
                });
            }
        }

        // Draw glowing Silvan arrow & starlight head
        function drawSilvanArrowHead(cx, cy, angle, scale) {
            ctx.save();
            ctx.translate(cx, cy);
            ctx.rotate(angle);
            ctx.scale(scale, scale);

            // Starlight glow
            ctx.shadowColor = '#f87171';
            ctx.shadowBlur = 18;

            // Shaft
            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 2.0;
            ctx.beginPath();
            ctx.moveTo(-22, 0);
            ctx.lineTo(26, 0);
            ctx.stroke();

            // Glowing arrowhead (pointing +X)
            ctx.fillStyle = '#ffffff';
            ctx.beginPath();
            ctx.moveTo(32, 0);
            ctx.lineTo(20, -5);
            ctx.lineTo(22, 0);
            ctx.lineTo(20, 5);
            ctx.closePath();
            ctx.fill();

            // Silvan fletching feathers at tail
            ctx.strokeStyle = '#ef4444';
            ctx.lineWidth = 1.4;
            ctx.beginPath();
            ctx.moveTo(-12, 0); ctx.lineTo(-20, -6);
            ctx.moveTo(-16, 0); ctx.lineTo(-24, -6);
            ctx.moveTo(-12, 0); ctx.lineTo(-20, 6);
            ctx.moveTo(-16, 0); ctx.lineTo(-24, 6);
            ctx.stroke();

            // Cross-star lens flare at tip
            const flareLen = 15 + Math.sin(frame * 0.3) * 4;
            ctx.strokeStyle = '#fff5f5';
            ctx.lineWidth = 1.5;
            ctx.beginPath();
            ctx.moveTo(32 - flareLen, 0); ctx.lineTo(32 + flareLen, 0);
            ctx.moveTo(32, -flareLen * 0.65); ctx.lineTo(32, flareLen * 0.65);
            ctx.stroke();

            ctx.restore();
        }

        function loop() {
            ctx.clearRect(0, 0, w, h);
            frame++;

            if (frame <= flightDuration) {
                const t = frame / flightDuration;
                const pos = getBezier(t);

                trail.push({ x: pos.x, y: pos.y, angle: pos.angle, time: frame });
                if (trail.length > 22) trail.shift();

                // Draw arced starlight ribbon
                for (let i = 1; i < trail.length; i++) {
                    const tr = trail[i];
                    const prev = trail[i - 1];
                    const trAlpha = (i / trail.length) * 0.88;
                    const trWidth = (i / trail.length) * 9.5;

                    ctx.save();
                    ctx.globalAlpha = trAlpha;
                    ctx.strokeStyle = '#ef4444';
                    ctx.shadowColor = '#f87171';
                    ctx.shadowBlur = 14;
                    ctx.lineWidth = trWidth;
                    ctx.lineCap = 'round';
                    ctx.beginPath();
                    ctx.moveTo(prev.x, prev.y);
                    ctx.lineTo(tr.x, tr.y);
                    ctx.stroke();

                    // Bright inner core
                    ctx.strokeStyle = '#ffffff';
                    ctx.lineWidth = Math.max(1, trWidth * 0.38);
                    ctx.stroke();
                    ctx.restore();
                }

                // Trailing stardust sparks
                for (let k = 0; k < 3; k++) {
                    const sparkAngle = pos.angle + Math.PI + (Math.random() - 0.5) * 1.2;
                    const spd = 0.5 + Math.random() * 2.5;
                    particles.push({
                        x: pos.x + (Math.random() - 0.5) * 8,
                        y: pos.y + (Math.random() - 0.5) * 8,
                        vx: Math.cos(sparkAngle) * spd,
                        vy: Math.sin(sparkAngle) * spd,
                        size: 1.4 + Math.random() * 2.4,
                        color: Math.random() > 0.4 ? '#ef4444' : (Math.random() > 0.4 ? '#ffffff' : '#f5d76e'),
                        alpha: 1.0,
                        decay: 0.025 + Math.random() * 0.025,
                        isImpact: false,
                        rot: Math.random() * Math.PI * 2,
                        vRot: (Math.random() - 0.5) * 0.1
                    });
                }

                // Draw Silvan arrow
                const headScale = 0.95 + Math.sin(frame * 0.25) * 0.08;
                drawSilvanArrowHead(pos.x, pos.y, pos.angle, headScale);
            }

            // Impact at quest card
            if (frame === flightDuration && !impactTriggered) {
                impactTriggered = true;
                spawnImpactParticles(tx, ty);

                shockwaves.push({ r: 4, maxR: 100, color: '#ef4444', width: 3.8, alpha: 1.0 });
                shockwaves.push({ r: 2, maxR: 80, color: '#f5d76e', width: 2.6, alpha: 1.0 });

                if (window.LotrEngine && window.LotrEngine.screenShake) {
                    window.LotrEngine.screenShake(7, 240);
                }

                // Illuminate the top-left quest card with gentle red/gold glow
                const freshQuestEl = document.querySelector('#quest-content .card') || document.querySelector('#quest-zone') || document.querySelector('.zone-quest');
                if (freshQuestEl) {
                    freshQuestEl.style.transition = 'transform 0.2s ease-out, box-shadow 0.2s ease, filter 0.2s ease';
                    freshQuestEl.style.filter = 'brightness(1.3) contrast(1.08)';
                    freshQuestEl.style.boxShadow = '0 0 25px rgba(239, 68, 68, 0.65), 0 0 45px rgba(245, 215, 110, 0.4)';
                    freshQuestEl.style.transform = 'scale(1.05)';
                    setTimeout(() => {
                        freshQuestEl.style.transition = 'all 0.6s cubic-bezier(0.25, 0.8, 0.25, 1)';
                        freshQuestEl.style.filter = '';
                        freshQuestEl.style.boxShadow = '';
                        freshQuestEl.style.transform = '';
                    }, 220);
                }

                // Floating text: +2 Progress! with 3.0s duration and non-overlapping stack offset
                const qCenter = freshQuestEl ? freshQuestEl.getBoundingClientRect() : qRect;
                const qCenterX = qCenter.left + qCenter.width / 2;
                const qCenterY = qCenter.top + qCenter.height / 2;

                window._questProgressStackCount = window._questProgressStackCount || 0;
                const stackIdx = window._questProgressStackCount;
                window._questProgressStackCount++;
                setTimeout(() => {
                    window._questProgressStackCount = Math.max(0, (window._questProgressStackCount || 1) - 1);
                }, 3000);
                const stackYOffset = stackIdx * 38;

                let style = document.getElementById('legolas-progress-text-style');
                if (!style) {
                    style = document.createElement('style');
                    style.id = 'legolas-progress-text-style';
                    document.head.appendChild(style);
                }
                style.textContent = `
                    @keyframes legolasProgressFloat {
                        0% { opacity: 0; transform: translate(-50%, -50%) scale(0.8); }
                        15% { opacity: 1; transform: translate(-50%, calc(-50% - 18px)) scale(1.18); }
                        75% { opacity: 1; transform: translate(-50%, calc(-50% - 35px)) scale(1); }
                        100% { opacity: 0; transform: translate(-50%, calc(-50% - 52px)) scale(0.9); }
                    }
                `;
                const floatTxt = document.createElement('div');
                floatTxt.textContent = '+2 Progress!';
                floatTxt.style.cssText = `
                    position: fixed; left: ${qCenterX}px; top: ${qCenterY - stackYOffset}px;
                    color: #f5d76e; font-family: 'Cinzel', serif; font-weight: 900; font-size: 2.3rem;
                    text-shadow: 0 2px 8px #000, 0 0 16px #ef4444, 0 0 30px rgba(245, 215, 110, 0.85);
                    z-index: 999999; pointer-events: none;
                    white-space: nowrap; text-align: center;
                    animation: legolasProgressFloat 3.0s ease-out forwards;
                `;
                document.body.appendChild(floatTxt);
                setTimeout(() => floatTxt.remove(), 3100);

                // Landing chime
                try {
                    const AudioCtx = window.AudioContext || window.webkitAudioContext;
                    if (AudioCtx) {
                        const actx = new AudioCtx();
                        const now = actx.currentTime;
                        [523.25, 659.25, 783.99, 1046.5].forEach((freq, i) => {
                            const osc = actx.createOscillator();
                            const gain = actx.createGain();
                            osc.type = 'sine';
                            osc.frequency.setValueAtTime(freq, now + i * 0.05);
                            gain.gain.setValueAtTime(0.1, now + i * 0.05);
                            gain.gain.exponentialRampToValueAtTime(0.0001, now + i * 0.05 + 0.75);
                            osc.connect(gain);
                            gain.connect(actx.destination);
                            osc.start(now + i * 0.05);
                            osc.stop(now + i * 0.05 + 0.8);
                        });
                    }
                } catch (e) {}

                if (onComplete) onComplete();
            }

            // Draw expanding shockwaves
            for (let i = shockwaves.length - 1; i >= 0; i--) {
                const sw = shockwaves[i];
                sw.r += 3.2;
                sw.alpha = Math.max(0, 1 - sw.r / sw.maxR);
                if (sw.alpha <= 0) {
                    shockwaves.splice(i, 1);
                    continue;
                }
                ctx.save();
                ctx.globalAlpha = sw.alpha;
                ctx.strokeStyle = sw.color;
                ctx.lineWidth = sw.width * sw.alpha;
                ctx.shadowColor = sw.color;
                ctx.shadowBlur = 12;
                ctx.beginPath();
                ctx.arc(tx, ty, sw.r, 0, Math.PI * 2);
                ctx.stroke();
                ctx.restore();
            }

            // Draw particles
            for (let i = particles.length - 1; i >= 0; i--) {
                const p = particles[i];
                p.x += p.vx;
                p.y += p.vy;
                p.alpha -= p.decay;
                p.rot += p.vRot;

                if (p.isImpact) {
                    p.vx *= 0.94;
                    p.vy = p.vy * 0.94 + 0.08;
                } else {
                    p.vx *= 0.97;
                    p.vy *= 0.97;
                }

                if (p.alpha <= 0) {
                    particles.splice(i, 1);
                    continue;
                }

                ctx.save();
                ctx.globalAlpha = Math.max(0, p.alpha);
                ctx.translate(p.x, p.y);
                ctx.rotate(p.rot);
                ctx.fillStyle = p.color;
                ctx.shadowColor = p.color;
                ctx.shadowBlur = p.size * 2;

                ctx.beginPath();
                ctx.arc(0, 0, p.size, 0, Math.PI * 2);
                ctx.fill();

                if (p.isImpact && p.size > 2.2) {
                    const ray = p.size * 1.8 * p.alpha;
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = 0.7;
                    ctx.beginPath();
                    ctx.moveTo(-ray, 0); ctx.lineTo(ray, 0);
                    ctx.moveTo(0, -ray); ctx.lineTo(0, ray);
                    ctx.stroke();
                }
                ctx.restore();
            }

            if (frame < flightDuration + 65 || particles.length > 0 || shockwaves.length > 0) {
                requestAnimationFrame(loop);
            } else {
                canvas.remove();
            }
        }
        requestAnimationFrame(loop);
    };

    // --- STRENGTH OF WILL: PROGRESS TRAVELLING EFFECT ---
    // When Strength of Will is used after travelling to a location, a radiant celestial Spirit projectile
    // shoots out from Strength of Will / Spirit character, arcing across the screen and landing
    // on the target location card with an explosion of starlight particles, glowing +2 Progress, and location illumination.
    window.triggerStrengthOfWillEffect = function(strengthCardUid, chosenCharUid, locUid, onImpact, onComplete) {
        let strengthEl = document.querySelector(`[data-uid="${strengthCardUid}"]`);
        const chosenEl = document.querySelector(`[data-uid="${chosenCharUid}"]`);
        let locEl = document.querySelector(`[data-uid="${locUid}"]`) || document.querySelector('#active-location-content .card') || document.querySelector('#active-location-zone') || document.querySelector('.zone-active-location');

        let sRect = null;
        if (strengthEl) {
            const rect = strengthEl.getBoundingClientRect();
            if (rect.width > 0 && rect.height > 0) sRect = rect;
        }
        if (!sRect && chosenEl) {
            const rect = chosenEl.getBoundingClientRect();
            if (rect.width > 0 && rect.height > 0) sRect = rect;
        }
        if (!sRect) {
            const handEl = document.getElementById('hand-content');
            sRect = handEl ? handEl.getBoundingClientRect() : { left: window.innerWidth / 2 - 45, top: window.innerHeight - 120, width: 90, height: 120 };
        }

        const lRect = locEl ? locEl.getBoundingClientRect() : { left: window.innerWidth / 2 - 60, top: window.innerHeight / 2 - 90, width: 120, height: 170 };

        const sx = sRect.left + sRect.width / 2;
        const sy = sRect.top + sRect.height / 2;
        const tx = lRect.left + lRect.width / 2;
        const ty = lRect.top + lRect.height / 2;

        // Sound effect
        if (window.SoundFX && typeof window.SoundFX.playStrengthOfWill === 'function') {
            window.SoundFX.playStrengthOfWill();
        }

        // Chime audio synthesis
        try {
            const AudioCtx = window.AudioContext || window.webkitAudioContext;
            if (AudioCtx) {
                const actx = new AudioCtx();
                const now = actx.currentTime;
                // E-major shimmering Spirit chord: 659.25, 830.61, 987.77, 1318.51, 1975.53
                [659.25, 830.61, 987.77, 1318.51, 1975.53].forEach((freq, i) => {
                    const osc = actx.createOscillator();
                    const gain = actx.createGain();
                    osc.type = 'sine';
                    osc.frequency.setValueAtTime(freq, now + i * 0.035);
                    gain.gain.setValueAtTime(0.09, now + i * 0.035);
                    gain.gain.exponentialRampToValueAtTime(0.0001, now + i * 0.035 + 0.7);
                    osc.connect(gain);
                    gain.connect(actx.destination);
                    osc.start(now + i * 0.035);
                    osc.stop(now + i * 0.035 + 0.75);
                });
            }
        } catch (e) {}

        // Pulse the chosen Spirit character card if available
        if (chosenEl) {
            const isExhausted = chosenEl.classList.contains('exhausted');
            const baseRotate = isExhausted ? 'rotate(90deg) ' : '';
            chosenEl.style.zIndex = '60';
            chosenEl.style.transition = 'transform 0.24s cubic-bezier(0.2, 0.9, 0.3, 1.2), box-shadow 0.24s ease, filter 0.24s ease';
            chosenEl.style.filter = 'brightness(1.75) contrast(1.18) drop-shadow(0 0 20px rgba(56, 189, 248, 0.7))';
            chosenEl.style.boxShadow = '0 0 35px rgba(56, 189, 248, 0.85), 0 0 60px rgba(0, 229, 255, 0.5), inset 0 0 25px rgba(220, 245, 255, 0.65)';
            chosenEl.style.transform = `${baseRotate}scale(1.16)`;
            setTimeout(() => {
                chosenEl.style.transition = 'transform 0.65s cubic-bezier(0.25, 1, 0.5, 1), box-shadow 0.65s ease, filter 0.65s ease';
                chosenEl.style.filter = '';
                chosenEl.style.boxShadow = '';
                chosenEl.style.transform = `${baseRotate}scale(1)`;
                setTimeout(() => {
                    chosenEl.style.transition = '';
                    chosenEl.style.transform = '';
                    chosenEl.style.zIndex = '';
                }, 700);
            }, 260);
        }

        // Full screen canvas
        const canvas = document.createElement('canvas');
        const dpr = window.devicePixelRatio || 1;
        const w = window.innerWidth;
        const h = window.innerHeight;
        canvas.width = w * dpr;
        canvas.height = h * dpr;
        canvas.style.cssText = `
            position: fixed; inset: 0; width: 100vw; height: 100vh;
            pointer-events: none; z-index: 999999;
        `;
        document.body.appendChild(canvas);

        const ctx = canvas.getContext('2d');
        ctx.scale(dpr, dpr);

        // Calculate arched trajectory
        const midX = (sx + tx) / 2;
        const midY = (sy + ty) / 2;
        const dist = Math.hypot(tx - sx, ty - sy) || 1;
        const arcHeight = Math.min(260, Math.max(130, dist * 0.32));
        const ctrlX = midX + (tx < sx ? 40 : -40);
        const ctrlY = Math.min(sy, ty) - arcHeight;

        function getBezier(t) {
            const inv = 1 - t;
            const x = inv * inv * sx + 2 * inv * t * ctrlX + t * t * tx;
            const y = inv * inv * sy + 2 * inv * t * ctrlY + t * t * ty;
            const dx = 2 * inv * (ctrlX - sx) + 2 * t * (tx - ctrlX);
            const dy = 2 * inv * (ctrlY - sy) + 2 * t * (ty - ctrlY);
            const angle = Math.atan2(dy, dx);
            return { x, y, angle };
        }

        const flightDuration = 56;
        let frame = 0;
        const trail = [];
        const particles = [];
        const shockwaves = [];
        const frostFlakes = [];
        const frostMists = [];
        let impactTriggered = false;

        function spawnImpactParticles(ix, iy) {
            for (let i = 0; i < 55; i++) {
                const angle = Math.random() * Math.PI * 2;
                const spd = 2.0 + Math.random() * 7.0;
                const colors = ['#ffffff', '#e0f2fe', '#38bdf8', '#00e5ff', '#f5d76e', '#ffd700', '#b388ff'];
                particles.push({
                    x: ix, y: iy,
                    vx: Math.cos(angle) * spd,
                    vy: Math.sin(angle) * spd - 0.5,
                    size: 1.8 + Math.random() * 3.8,
                    color: colors[Math.floor(Math.random() * colors.length)],
                    alpha: 1.0,
                    decay: 0.015 + Math.random() * 0.02,
                    isImpact: true,
                    rot: Math.random() * Math.PI * 2,
                    vRot: (Math.random() - 0.5) * 0.15
                });
            }
        }

        // Swirling Frost Storm that sweeps across the target location card
        function spawnFrostStorm(r) {
            const lx = r.left;
            const ly = r.top;
            const lw = r.width;
            const lh = r.height;

            // 1. Chilled Frost Mist clouds lingering and slowly billowing across card face
            for (let i = 0; i < 26; i++) {
                frostMists.push({
                    x: lx - 30 + Math.random() * (lw * 0.7),
                    y: ly - 10 + Math.random() * (lh + 20),
                    vx: 0.25 + Math.random() * 0.45,
                    vy: (Math.random() - 0.5) * 0.2,
                    radius: 40 + Math.random() * 48,
                    alpha: 0.55 + Math.random() * 0.3,
                    decay: 0.0016 + Math.random() * 0.0014 // Lasts a little bit longer
                });
            }

            // 2. Abundant Frost Flakes (180 flakes) gently drifting and looping in the wind
            for (let i = 0; i < 180; i++) {
                const isIceStar = Math.random() < 0.55;
                const isLooping = Math.random() < 0.40; // Caught in swirling wind loops
                frostFlakes.push({
                    x: lx - 40 + Math.random() * (lw + 65),
                    y: ly - 25 + Math.random() * (lh + 45),
                    vx: isLooping ? (0.4 + Math.random() * 0.5) : (0.6 + Math.random() * 1.0),
                    vy: (Math.random() - 0.5) * 0.45,
                    swayFreq: 0.022 + Math.random() * 0.02,
                    swayAmp: 1.2 + Math.random() * 1.6,
                    size: isIceStar ? (2.0 + Math.random() * 3.2) : (1.2 + Math.random() * 1.8),
                    rot: Math.random() * Math.PI * 2,
                    vRot: (Math.random() - 0.5) * 0.05,
                    alpha: 1.0,
                    decay: 0.0026 + Math.random() * 0.0022, // Lasts a tiny bit less
                    isIceStar: isIceStar,
                    isLooping: isLooping,
                    loopRadius: 14 + Math.random() * 18,
                    loopSpeed: 0.038 + Math.random() * 0.032,
                    loopAngle: Math.random() * Math.PI * 2,
                    loopTilt: 0.42 + Math.random() * 0.25
                });
            }
        }

        // Draw radiant Willpower / Spirit Star at projectile head
        function drawStrengthOfWillHead(cx, cy, angle, scale, time) {
            ctx.save();
            ctx.translate(cx, cy);
            ctx.scale(scale, scale);

            // Outer radiant azure & lavender starlight aura
            const outerGrad = ctx.createRadialGradient(0, 0, 2, 0, 0, 32);
            outerGrad.addColorStop(0, 'rgba(255, 255, 255, 0.98)');
            outerGrad.addColorStop(0.25, 'rgba(178, 235, 242, 0.92)');
            outerGrad.addColorStop(0.55, 'rgba(0, 229, 255, 0.70)');
            outerGrad.addColorStop(0.80, 'rgba(179, 136, 255, 0.35)');
            outerGrad.addColorStop(1, 'rgba(0, 229, 255, 0)');
            ctx.fillStyle = outerGrad;
            ctx.beginPath();
            ctx.arc(0, 0, 32, 0, Math.PI * 2);
            ctx.fill();

            // Rotating 4-point golden celestial star
            ctx.save();
            ctx.rotate(time * 0.08);
            ctx.fillStyle = '#f5d76e';
            ctx.shadowColor = '#ffd700';
            ctx.shadowBlur = 15;
            ctx.beginPath();
            const starR1 = 20 + Math.sin(time * 0.3) * 4;
            const starR2 = 5;
            for (let i = 0; i < 8; i++) {
                const r = i % 2 === 0 ? starR1 : starR2;
                const a = (i * Math.PI) / 4;
                if (i === 0) ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r);
                else ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
            }
            ctx.closePath();
            ctx.fill();
            ctx.restore();

            // Shimmering white/cyan core
            ctx.fillStyle = '#ffffff';
            ctx.shadowColor = '#00e5ff';
            ctx.shadowBlur = 18;
            ctx.beginPath();
            ctx.arc(0, 0, 8.5, 0, Math.PI * 2);
            ctx.fill();

            // Inner cyan rim
            ctx.strokeStyle = '#80deea';
            ctx.lineWidth = 1.8;
            ctx.beginPath();
            ctx.arc(0, 0, 8.5, 0, Math.PI * 2);
            ctx.stroke();

            // Orbiting helical willpower motes (in 3D perspective)
            for (let m = 0; m < 2; m++) {
                const phase = time * 0.25 + m * Math.PI;
                const orbDistX = Math.cos(phase) * 19;
                const orbDistY = Math.sin(phase) * 8;
                ctx.save();
                ctx.translate(orbDistX, orbDistY);
                ctx.fillStyle = m === 0 ? '#ffffff' : '#ffd700';
                ctx.shadowColor = m === 0 ? '#38bdf8' : '#f5d76e';
                ctx.shadowBlur = 10;
                ctx.beginPath();
                ctx.arc(0, 0, 3.2, 0, Math.PI * 2);
                ctx.fill();
                ctx.restore();
            }

            ctx.restore();
        }

        function loop() {
            ctx.clearRect(0, 0, w, h);
            frame++;

            if (frame <= flightDuration) {
                const t = frame / flightDuration;
                const pos = getBezier(t);

                // Add to ribbon trail
                trail.push({ x: pos.x, y: pos.y, angle: pos.angle, time: frame });
                if (trail.length > 24) trail.shift();

                // Draw starlight comet tail ribbon
                for (let i = 1; i < trail.length; i++) {
                    const tr = trail[i];
                    const prev = trail[i - 1];
                    const trAlpha = (i / trail.length) * 0.88;
                    const trWidth = (i / trail.length) * 11.0;

                    ctx.save();
                    ctx.globalAlpha = trAlpha;
                    ctx.strokeStyle = '#00e5ff';
                    ctx.shadowColor = '#38bdf8';
                    ctx.shadowBlur = 16;
                    ctx.lineWidth = trWidth;
                    ctx.lineCap = 'round';
                    ctx.beginPath();
                    ctx.moveTo(prev.x, prev.y);
                    ctx.lineTo(tr.x, tr.y);
                    ctx.stroke();

                    // Bright inner white/gold core
                    ctx.strokeStyle = (i % 2 === 0) ? '#ffffff' : '#f5d76e';
                    ctx.lineWidth = Math.max(1.2, trWidth * 0.38);
                    ctx.stroke();
                    ctx.restore();
                }

                // Spawn trailing stardust sparks
                for (let k = 0; k < 4; k++) {
                    const sparkAngle = pos.angle + Math.PI + (Math.random() - 0.5) * 1.4;
                    const spd = 0.6 + Math.random() * 3.0;
                    particles.push({
                        x: pos.x + (Math.random() - 0.5) * 10,
                        y: pos.y + (Math.random() - 0.5) * 10,
                        vx: Math.cos(sparkAngle) * spd,
                        vy: Math.sin(sparkAngle) * spd,
                        size: 1.5 + Math.random() * 2.8,
                        color: Math.random() > 0.4 ? '#00e5ff' : (Math.random() > 0.5 ? '#ffffff' : '#f5d76e'),
                        alpha: 1.0,
                        decay: 0.022 + Math.random() * 0.022,
                        isImpact: false,
                        rot: Math.random() * Math.PI * 2,
                        vRot: (Math.random() - 0.5) * 0.12
                    });
                }

                // Draw the glowing Willpower Star head
                const headScale = 1.0 + Math.sin(frame * 0.3) * 0.1;
                drawStrengthOfWillHead(pos.x, pos.y, pos.angle, headScale, frame);
            }

            // Impact at location card
            if (frame === flightDuration && !impactTriggered) {
                impactTriggered = true;
                spawnImpactParticles(tx, ty);

                // Expanding shockwaves
                shockwaves.push({ r: 4, maxR: 110, color: '#00e5ff', width: 4.0, alpha: 1.0 });
                shockwaves.push({ r: 2, maxR: 85, color: '#f5d76e', width: 2.8, alpha: 1.0 });
                shockwaves.push({ r: 1, maxR: 65, color: '#ffffff', width: 2.0, alpha: 1.0 });

                // Re-find location element for accurate visual illumination and frost storm bounds
                const freshLocEl = document.querySelector(`[data-uid="${locUid}"]`) || document.querySelector('#active-location-content .card') || document.querySelector('#active-location-zone') || document.querySelector('.zone-active-location');
                const locBounds = freshLocEl ? freshLocEl.getBoundingClientRect() : lRect;

                // Launch Frost Storm across location card
                spawnFrostStorm(locBounds);

                if (window.LotrEngine && window.LotrEngine.screenShake) {
                    window.LotrEngine.screenShake(7, 260);
                }

                if (freshLocEl) {
                    freshLocEl.style.transition = 'transform 0.22s cubic-bezier(0.2, 0.9, 0.3, 1.2), box-shadow 0.25s ease, filter 0.25s ease';
                    freshLocEl.style.filter = 'brightness(1.48) contrast(1.18) drop-shadow(0 0 26px rgba(0, 229, 255, 0.95)) drop-shadow(0 0 45px rgba(186, 230, 253, 0.75))';
                    freshLocEl.style.boxShadow = '0 0 38px rgba(0, 229, 255, 0.92), 0 0 65px rgba(125, 211, 252, 0.75), inset 0 0 25px rgba(255, 255, 255, 0.9)';
                    freshLocEl.style.transform = 'scale(1.08)';
                    setTimeout(() => {
                        freshLocEl.style.transition = 'all 0.85s cubic-bezier(0.25, 0.8, 0.25, 1)';
                        freshLocEl.style.filter = '';
                        freshLocEl.style.boxShadow = '';
                        freshLocEl.style.transform = '';
                    }, 400);
                }

                // Floating text: +2 Progress!
                const locCenter = freshLocEl ? freshLocEl.getBoundingClientRect() : lRect;
                const locCenterX = locCenter.left + locCenter.width / 2;
                const locCenterY = locCenter.top + locCenter.height / 2;

                let style = document.getElementById('strength-of-will-text-style');
                if (!style) {
                    style = document.createElement('style');
                    style.id = 'strength-of-will-text-style';
                    document.head.appendChild(style);
                }
                style.textContent = `
                    @keyframes strengthOfWillFloat {
                        0% { opacity: 0; transform: translate(-50%, -50%) scale(0.8); }
                        15% { opacity: 1; transform: translate(-50%, calc(-50% - 18px)) scale(1.18); }
                        75% { opacity: 1; transform: translate(-50%, calc(-50% - 35px)) scale(1); }
                        100% { opacity: 0; transform: translate(-50%, calc(-50% - 52px)) scale(0.9); }
                    }
                `;
                const floatTxt = document.createElement('div');
                floatTxt.textContent = '+2 Progress!';
                floatTxt.style.cssText = `
                    position: fixed; left: ${locCenterX}px; top: ${locCenterY}px;
                    color: #f5d76e; font-family: 'Cinzel', serif; font-weight: 900; font-size: 2.3rem;
                    text-shadow: 0 2px 8px #000, 0 0 16px #00e5ff, 0 0 30px rgba(245, 215, 110, 0.85);
                    z-index: 999999; pointer-events: none;
                    white-space: nowrap; text-align: center;
                    animation: strengthOfWillFloat 3.0s ease-out forwards;
                `;
                document.body.appendChild(floatTxt);
                setTimeout(() => floatTxt.remove(), 3100);

                // Landing chime
                try {
                    const AudioCtx = window.AudioContext || window.webkitAudioContext;
                    if (AudioCtx) {
                        const actx = new AudioCtx();
                        const now = actx.currentTime;
                        [523.25, 659.25, 783.99, 1046.5, 1318.51].forEach((freq, i) => {
                            const osc = actx.createOscillator();
                            const gain = actx.createGain();
                            osc.type = 'sine';
                            osc.frequency.setValueAtTime(freq, now + i * 0.045);
                            gain.gain.setValueAtTime(0.1, now + i * 0.045);
                            gain.gain.exponentialRampToValueAtTime(0.0001, now + i * 0.045 + 0.75);
                            osc.connect(gain);
                            gain.connect(actx.destination);
                            osc.start(now + i * 0.045);
                            osc.stop(now + i * 0.045 + 0.8);
                        });
                    }
                } catch (e) {}

                if (onImpact) onImpact();
                if (onComplete) onComplete();
            }

            // Draw shockwaves
            for (let i = shockwaves.length - 1; i >= 0; i--) {
                const sw = shockwaves[i];
                sw.r += 3.4;
                sw.alpha = Math.max(0, 1 - sw.r / sw.maxR);
                if (sw.alpha <= 0) {
                    shockwaves.splice(i, 1);
                    continue;
                }
                ctx.save();
                ctx.globalAlpha = sw.alpha;
                ctx.strokeStyle = sw.color;
                ctx.lineWidth = sw.width * sw.alpha;
                ctx.shadowColor = sw.color;
                ctx.shadowBlur = 14;
                ctx.beginPath();
                ctx.arc(tx, ty, sw.r, 0, Math.PI * 2);
                ctx.stroke();
                ctx.restore();
            }

            // Draw particles
            for (let i = particles.length - 1; i >= 0; i--) {
                const p = particles[i];
                p.x += p.vx;
                p.y += p.vy;
                p.alpha -= p.decay;
                p.rot += p.vRot;

                if (p.isImpact) {
                    p.vx *= 0.94;
                    p.vy = p.vy * 0.94 + 0.08;
                } else {
                    p.vx *= 0.97;
                    p.vy *= 0.97;
                }

                if (p.alpha <= 0) {
                    particles.splice(i, 1);
                    continue;
                }

                ctx.save();
                ctx.globalAlpha = Math.max(0, p.alpha);
                ctx.translate(p.x, p.y);
                ctx.rotate(p.rot);
                ctx.fillStyle = p.color;
                ctx.shadowColor = p.color;
                ctx.shadowBlur = p.size * 2;

                ctx.beginPath();
                ctx.arc(0, 0, p.size, 0, Math.PI * 2);
                ctx.fill();

                if (p.isImpact && p.size > 2.2) {
                    const ray = p.size * 1.8 * p.alpha;
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = 0.7;
                    ctx.beginPath();
                    ctx.moveTo(-ray, 0); ctx.lineTo(ray, 0);
                    ctx.moveTo(0, -ray); ctx.lineTo(0, ray);
                    ctx.stroke();
                }
                ctx.restore();
            }

            // Draw Frost Mist Clouds over location
            for (let i = frostMists.length - 1; i >= 0; i--) {
                const m = frostMists[i];
                m.x += m.vx;
                m.y += m.vy;
                m.alpha -= m.decay;

                if (m.alpha <= 0) {
                    frostMists.splice(i, 1);
                    continue;
                }

                ctx.save();
                ctx.globalCompositeOperation = 'screen';
                ctx.globalAlpha = Math.max(0, m.alpha);
                const mGrad = ctx.createRadialGradient(m.x, m.y, 0, m.x, m.y, m.radius);
                mGrad.addColorStop(0, 'rgba(255, 255, 255, 0.85)');
                mGrad.addColorStop(0.35, 'rgba(186, 230, 253, 0.55)');
                mGrad.addColorStop(0.7, 'rgba(56, 189, 248, 0.25)');
                mGrad.addColorStop(1, 'rgba(0, 229, 255, 0)');
                ctx.fillStyle = mGrad;
                ctx.beginPath();
                ctx.arc(m.x, m.y, m.radius, 0, Math.PI * 2);
                ctx.fill();
                ctx.restore();
            }

            // Draw Swirling Frost Crystals & Looping Snowflakes
            for (let i = frostFlakes.length - 1; i >= 0; i--) {
                const f = frostFlakes[i];

                if (f.isLooping) {
                    // Circular vortex loop-the-loop movement
                    f.loopAngle += f.loopSpeed;
                    f.x += f.vx + Math.cos(f.loopAngle) * (f.loopRadius * f.loopSpeed * 1.65);
                    f.y += f.vy + Math.sin(f.loopAngle) * (f.loopRadius * f.loopSpeed * 1.65 * f.loopTilt);
                } else {
                    // Gentle forward drift with sinusoidal sway
                    f.x += f.vx;
                    f.y += f.vy + Math.sin(frame * f.swayFreq) * f.swayAmp;
                }

                f.rot += f.vRot;
                f.alpha -= f.decay;

                if (f.alpha <= 0) {
                    frostFlakes.splice(i, 1);
                    continue;
                }

                ctx.save();
                ctx.globalAlpha = Math.max(0, f.alpha);
                ctx.translate(f.x, f.y);
                ctx.rotate(f.rot);

                if (f.isIceStar) {
                    ctx.shadowColor = '#00e5ff';
                    ctx.shadowBlur = 8;
                    ctx.strokeStyle = '#ffffff';
                    ctx.lineWidth = 0.9;
                    const r = f.size * 1.5;
                    ctx.beginPath();
                    ctx.moveTo(-r, 0); ctx.lineTo(r, 0);
                    ctx.moveTo(0, -r); ctx.lineTo(0, r);
                    ctx.moveTo(-r * 0.7, -r * 0.7); ctx.lineTo(r * 0.7, r * 0.7);
                    ctx.moveTo(-r * 0.7, r * 0.7); ctx.lineTo(r * 0.7, -r * 0.7);
                    ctx.stroke();

                    ctx.fillStyle = '#bae6fd';
                    ctx.beginPath();
                    ctx.arc(0, 0, Math.max(0.6, f.size * 0.35), 0, Math.PI * 2);
                    ctx.fill();
                } else {
                    ctx.fillStyle = '#e0f7fa';
                    ctx.shadowColor = '#38bdf8';
                    ctx.shadowBlur = 6;
                    ctx.beginPath();
                    ctx.arc(0, 0, f.size * 0.6, 0, Math.PI * 2);
                    ctx.fill();
                }
                ctx.restore();
            }

            if (frame < flightDuration + 320 || particles.length > 0 || shockwaves.length > 0 || frostFlakes.length > 0 || frostMists.length > 0) {
                requestAnimationFrame(loop);
            } else {
                canvas.remove();
            }
        }
        requestAnimationFrame(loop);
    };

    window.startHornOfGondorAura = function(heroUid) {
        if (_activeHornOfGondorCanvases.has(heroUid)) return;
        const el = document.querySelector(`[data-uid="${heroUid}"]`);
        if (!el) return;
        const rect = el.getBoundingClientRect();

        const padX = 60;
        const padTop = 140;
        const padBottom = 35;
        let curCardW = rect.width;
        let curCardH = rect.height;
        let curWidth = curCardW + padX * 2;
        let curHeight = curCardH + padTop + padBottom;

        const canvas = document.createElement('canvas');
        canvas.className = 'horn-of-gondor-aura-canvas';
        _activeHornOfGondorCanvases.set(heroUid, canvas);
        const dpr = window.devicePixelRatio || 1;
        canvas.width = curWidth * dpr;
        canvas.height = curHeight * dpr;
        canvas.style.cssText = `
            position: fixed; left: ${rect.left - padX}px; top: ${rect.top - padTop}px;
            width: ${curWidth}px; height: ${curHeight}px; pointer-events: none; z-index: 80;
        `;
        document.body.appendChild(canvas);

        const ctx = canvas.getContext('2d');
        ctx.scale(dpr, dpr);
        const particles = [];

        function spawnEmber() {
            if (Math.random() < 0.42) {
                particles.push({
                    x: padX + Math.random() * curCardW,
                    y: padTop + curCardH * 0.4 + Math.random() * (curCardH * 0.6),
                    vx: (Math.random() - 0.5) * 0.8,
                    vy: -0.8 - Math.random() * 1.5,
                    size: 1.4 + Math.random() * 2.0,
                    life: 1.0,
                    decay: 0.015 + Math.random() * 0.018,
                    color: Math.random() > 0.4 ? '#fef08a' : (Math.random() > 0.5 ? '#f5d76e' : '#ffffff')
                });
            }
        }

        function loop() {
            ctx.clearRect(0, 0, curWidth, curHeight);

            const game = window.LotrEngine?.game;
            const heroInPlay = [...(game?.heroes || []), ...(game?.allies || [])].find(c => c._uid === heroUid);
            const isAttached = heroInPlay && !heroInPlay._dead && heroInPlay.attached && heroInPlay.attached.some(a => a.id === 'horn_of_gondor');

            const freshEl = document.querySelector(`[data-uid="${heroUid}"]`);
            if (!freshEl || freshEl.style.visibility === 'hidden' || freshEl.style.opacity === '0' || freshEl.offsetParent === null) {
                canvas.style.display = 'none';
            } else {
                canvas.style.display = 'block';
                const fRect = freshEl.getBoundingClientRect();
                const newCardW = fRect.width;
                const newCardH = fRect.height;
                const newWidth = newCardW + padX * 2;
                const newHeight = newCardH + padTop + padBottom;

                if (curWidth !== newWidth || curHeight !== newHeight) {
                    curCardW = newCardW;
                    curCardH = newCardH;
                    curWidth = newWidth;
                    curHeight = newHeight;
                    canvas.width = curWidth * dpr;
                    canvas.height = curHeight * dpr;
                    canvas.style.width = `${curWidth}px`;
                    canvas.style.height = `${curHeight}px`;
                    ctx.scale(dpr, dpr);
                }

                canvas.style.left = `${fRect.left - padX}px`;
                canvas.style.top = `${fRect.top - padTop}px`;
            }

            if (isAttached && canvas.style.display !== 'none') {
                spawnEmber();
            }

            for (let i = particles.length - 1; i >= 0; i--) {
                const p = particles[i];
                p.x += p.vx;
                p.y += p.vy;
                p.life -= p.decay;
                if (p.life <= 0) {
                    particles.splice(i, 1);
                    continue;
                }
                ctx.save();
                ctx.globalAlpha = Math.max(0, p.life * 0.9);
                ctx.fillStyle = p.color;
                ctx.shadowColor = '#f5d76e';
                ctx.shadowBlur = 6;
                ctx.beginPath();
                ctx.arc(p.x, p.y, p.size * p.life, 0, Math.PI * 2);
                ctx.fill();
                ctx.restore();
            }

            if (isAttached || particles.length > 0) {
                requestAnimationFrame(loop);
            } else {
                canvas.remove();
                _activeHornOfGondorCanvases.delete(heroUid);
            }
        }
        requestAnimationFrame(loop);
    };

