    _coneHGrad.addColorStop(0.44, 'rgba(255, 240, 180, 0.65)');
    _coneHGrad.addColorStop(0.5, 'rgba(255, 255, 255, 0.95)');
    _coneHGrad.addColorStop(0.56, 'rgba(255, 240, 180, 0.65)');
    _coneHGrad.addColorStop(0.75, 'rgba(245, 215, 110, 0.18)');
    _coneHGrad.addColorStop(1, 'rgba(212, 175, 55, 0)');
    _lcCtx.fillStyle = _coneHGrad;
    _lcCtx.beginPath();
    _lcCtx.moveTo(128, 0);
    _lcCtx.lineTo(256, 512);
