        const handZone = document.getElementById('hand-content');
        if (handZone) {
            const hzr = handZone.getBoundingClientRect();
            if (hzr.width > 0 && hzr.height > 0) {
                sRect = { left: hzr.left + hzr.width / 2 - 60, top: hzr.top + 10, width: 120, height: 168 };
            }
        }
