            ctx.quadraticCurveTo(-6, 6, 2, 7); // Underbelly
            ctx.quadraticCurveTo(14, 8, 28, 0); // Chin
            ctx.closePath();
            ctx.fill();

            // Diamond Beak of Pure Light
            ctx.fillStyle = '#ffffff';
            ctx.beginPath();
            ctx.moveTo(28, 0);
            ctx.lineTo(21, -3);
            ctx.lineTo(19, 0);
            ctx.lineTo(21, 3);
            ctx.closePath();
            ctx.fill();

            // Piercing Spirit Eyes
            ctx.fillStyle = '#00f0ff';
            ctx.shadowColor = '#00f0ff';
            ctx.shadowBlur = 12;
